#!/bin/bash
# The initializr's Gradle downloads, generated by the real generator with its
# shipped templates, built with their own wrapper:
#
#  1. "App" and "App + backend" compile (the backend as a subproject);
#  2. "Backend only" holds a server and nothing of a client app -- no
#     codenameone_settings.properties, theme, simulator or native trees;
#  3. its runBackend serves the template's /healthz on the JVM;
#  4. backendPackage translates it to a native binary (skipped without clang,
#     unless CN1_BACKEND_PACKAGE_REQUIRED=1), and the binary serves /healthz.
#  5. "Command-line tool" runs its command with arguments, on the JVM and as a
#     native binary, with picocli's exit codes and generated help;
#  6. the same download with its command written in Python (argparse) instead
#     runs, packages and exits the way CPython would;
#  7. its migration tasks say so when there is nothing to migrate, and apply,
#     list and validate a script once there is one.
#
# Needs the reactor installed (mvn install) and a JDK 17+; see inc/gradle.sh.
SCRIPTPATH="$( cd "$(dirname "$0")" ; pwd -P )"
set -e
source "$SCRIPTPATH/inc/env.sh"
source "$SCRIPTPATH/inc/gradle.sh"

WORKDIR="$SCRIPTPATH/build/gradle-initializr"
rm -rf "$WORKDIR"
mkdir -p "$WORKDIR/fixtures"

# The real generator, with its shipped templates (the same run the initializr
# fixture test makes). It compiles with --release 8, so it needs a JDK 9+ javac.
PATH="$GRADLE_JDK/bin:$PATH" CN1_TEST_MAVEN_REPOSITORY="$CN1_REPO" \
  python3 "$SCRIPTPATH/../../scripts/tests/generate-initializr-fixtures.py" "$WORKDIR/fixtures" \
  > "$WORKDIR/fixtures.log" 2>&1 || { cat "$WORKDIR/fixtures.log"; fail "generating the initializr downloads"; }

# download-name dir -- extracts one download and points it at the local plugin
extract() {
  mkdir -p "$2"
  unzip -q "$WORKDIR/fixtures/$1" -d "$2"
  use_local_plugin "$2"
}

echo "== App"
extract GRADLE-APP-INTELLIJ.zip "$WORKDIR/app"
[ ! -e "$WORKDIR/app/backend" ] || fail "the App download has a backend"
run_gradle "$WORKDIR/app" classes cn1Css > "$WORKDIR/app.log" 2>&1 || { cat "$WORKDIR/app.log"; fail "the App download does not build"; }

echo "== App + backend"
extract GRADLE-APP_WITH_BACKEND-NETBEANS.zip "$WORKDIR/appbackend"
[ -f "$WORKDIR/appbackend/backend/application.properties" ] || fail "the App + backend download has no backend"
run_gradle "$WORKDIR/appbackend" classes :backend:classes > "$WORKDIR/appbackend.log" 2>&1 \
  || { cat "$WORKDIR/appbackend.log"; fail "the App + backend download does not build"; }

echo "== Backend only"
SVC="$WORKDIR/launcherprobe"
mkdir -p "$SVC"
unzip -q "$WORKDIR/fixtures/GRADLE-BACKEND_ONLY-VS_CODE.zip" -d "$SVC"
use_local_plugin "$SVC"

echo "== layout"
for f in settings.gradle.kts build.gradle.kts gradlew application.properties application-dev.properties; do
  [ -e "$SVC/$f" ] || fail "backend-only download is missing $f"
done
for f in codenameone_settings.properties src/main/css pom.xml common backend src/android src/ios src/javase; do
  [ ! -e "$SVC/$f" ] || fail "backend-only download should not have $f"
done
API=$(find "$SVC/src/main/java" -name Api.java | head -1)
[ -n "$API" ] || fail "no Api.java controller"

echo "== tasks"
run_gradle "$SVC" tasks --group "codename one" > "$WORKDIR/tasks.log" 2>&1 || { cat "$WORKDIR/tasks.log"; fail "tasks"; }
for t in runBackend backendPackage backendTest cn1Update; do
  grep -q "^$t " "$WORKDIR/tasks.log" || { cat "$WORKDIR/tasks.log"; fail "a backend offers $t"; }
done
for t in cn1Css buildAndroid generateNativeInterfaces run; do
  if grep -q "^$t " "$WORKDIR/tasks.log"; then fail "a backend-only project should not offer $t"; fi
done

echo "== runBackend"
check_backend_healthz "$SVC" runBackend "$WORKDIR/run.log"

echo "== test"
# The sample tests on the JVM, counted from the reports: a test task that found
# no engine runs nothing and succeeds.
run_gradle "$SVC" test > "$WORKDIR/test.log" 2>&1 || { cat "$WORKDIR/test.log"; fail "test"; }
backend_tests_ran() {
  local total=0 count report
  for report in "$SVC"/build/test-results/test/TEST-*.xml; do
    [ -f "$report" ] || continue
    count="$(sed -n 's/.*<testsuite[^>]* tests="\([0-9]*\)".*/\1/p' "$report" | head -1)"
    total=$((total + ${count:-0}))
  done
  echo "$total"
}
JVM_TESTS="$(backend_tests_ran)"
[ "$JVM_TESTS" -ge 3 ] || { cat "$WORKDIR/test.log"; fail "the backend's sample tests did not run (counted $JVM_TESTS)"; }
echo "   $JVM_TESTS tests on the JVM"

echo "== backendPackage"
if command -v clang > /dev/null 2>&1; then
  run_gradle "$SVC" backendTest > "$WORKDIR/backendtest.log" 2>&1 || { cat "$WORKDIR/backendtest.log"; fail "backendTest"; }
  COMPILED=0
  for report in "$SVC"/build/surefire-reports/TEST-*-compiled.xml; do
    [ -f "$report" ] || continue
    count="$(sed -n 's/.*<testsuite[^>]* tests="\([0-9]*\)".*/\1/p' "$report" | head -1)"
    COMPILED=$((COMPILED + ${count:-0}))
  done
  [ "$COMPILED" -ge 3 ] || { cat "$WORKDIR/backendtest.log"; fail "the sample tests did not run compiled (counted $COMPILED)"; }
  echo "   $COMPILED tests compiled"
  run_gradle "$SVC" backendPackage > "$WORKDIR/package.log" 2>&1 || { cat "$WORKDIR/package.log"; fail "backendPackage"; }
  BIN="$SVC/build/launcherprobe"
  [ -x "$BIN" ] || { cat "$WORKDIR/package.log"; fail "backendPackage produced no executable at $BIN"; }
  echo "   $(du -h "$BIN" | cut -f1) binary"
  check_binary_healthz "$BIN" "$SVC" "$WORKDIR/binary.log"
elif [ "${CN1_BACKEND_PACKAGE_REQUIRED:-}" = "1" ]; then
  fail "backendPackage needs clang, and CN1_BACKEND_PACKAGE_REQUIRED=1 forbids skipping it"
else
  echo "   skipped: no clang on PATH"
fi

echo "== Command-line tool"
CLI="$WORKDIR/cli/launcherprobe"
mkdir -p "$CLI"
unzip -q "$WORKDIR/fixtures/GRADLE-COMMAND_LINE-INTELLIJ.zip" -d "$CLI"
use_local_plugin "$CLI"
[ -n "$(find "$CLI/src/main/java" -name Hello.java)" ] || fail "no Hello.java command"
[ -z "$(find "$CLI/src" -name Api.java)" ] || fail "a command-line tool should not have a controller"
run_gradle "$CLI" runBackend "-Pcn1.backend.args=--count 2 --loud Ada" > "$WORKDIR/cli-run.log" 2>&1 \
  || { cat "$WORKDIR/cli-run.log"; fail "runBackend with arguments"; }
[ "$(grep -c '^HELLO, ADA!$' "$WORKDIR/cli-run.log")" = "2" ] \
  || { cat "$WORKDIR/cli-run.log"; fail "the command did not run with its arguments on the JVM"; }
run_gradle "$CLI" test > "$WORKDIR/cli-test.log" 2>&1 || { cat "$WORKDIR/cli-test.log"; fail "the tool's tests"; }
# binary -- runs the packaged tool through every outcome a caller sees
check_cli_binary() {
  local bin="$1" out code
  out="$("$bin" -c 3 Ada)" || fail "the binary failed on valid arguments"
  [ "$(printf '%s\n' "$out" | grep -c '^Hello, Ada$')" = "3" ] || fail "the binary printed: $out"
  out="$("$bin" --help)" || fail "--help did not exit 0"
  printf '%s\n' "$out" | grep -q 'Usage: ' || fail "--help printed no usage: $out"
  printf '%s\n' "$out" | grep -q -- '--count=<count>' || fail "--help did not list --count: $out"
  out="$("$bin" --version)" || fail "--version did not exit 0"
  printf '%s\n' "$out" | grep -q ' 1.0$' || fail "--version printed: $out"
  set +e
  "$bin" --no-such-option Ada > "$WORKDIR/cli-bad.log" 2>&1; code=$?
  "$bin" > "$WORKDIR/cli-missing.log" 2>&1; local missing=$?
  set -e
  [ "$code" = "2" ] || { cat "$WORKDIR/cli-bad.log"; fail "an unknown option exited $code, not 2"; }
  grep -q "Unknown option: '--no-such-option'" "$WORKDIR/cli-bad.log" || { cat "$WORKDIR/cli-bad.log"; fail "unknown option message"; }
  [ "$missing" = "2" ] || { cat "$WORKDIR/cli-missing.log"; fail "a missing parameter exited $missing, not 2"; }
}
if command -v clang > /dev/null 2>&1; then
  run_gradle "$CLI" backendPackage > "$WORKDIR/cli-package.log" 2>&1 || { cat "$WORKDIR/cli-package.log"; fail "backendPackage for the tool"; }
  [ -x "$CLI/build/launcherprobe" ] || { cat "$WORKDIR/cli-package.log"; fail "no executable at $CLI/build/launcherprobe"; }
  echo "   $(du -h "$CLI/build/launcherprobe" | cut -f1) binary"
  check_cli_binary "$CLI/build/launcherprobe"
elif [ "${CN1_BACKEND_PACKAGE_REQUIRED:-}" = "1" ]; then
  fail "backendPackage needs clang, and CN1_BACKEND_PACKAGE_REQUIRED=1 forbids skipping it"
else
  echo "   native binary skipped: no clang on PATH"
fi

echo "== Command-line tool in Python"
# The Java command replaced by a Python program: src/main/python transpiles,
# its main module becomes the entry point, and argparse, sys.exit and an
# uncaught exception give the exit statuses CPython gives.
PYCLI="$WORKDIR/pycli/launcherprobe"
mkdir -p "$PYCLI"
unzip -q "$WORKDIR/fixtures/GRADLE-COMMAND_LINE-INTELLIJ.zip" -d "$PYCLI"
use_local_plugin "$PYCLI"
find "$PYCLI/src" -name 'Hello*.java' -exec rm {} +
mkdir -p "$PYCLI/src/main/python"
cat > "$PYCLI/src/main/python/main.py" <<'PY'
import argparse
import sys


def main(argv=None):
    parser = argparse.ArgumentParser(description="Prints a greeting.")
    parser.add_argument("name", help="who to greet")
    parser.add_argument("-c", "--count", type=int, default=1, help="how many times")
    parser.add_argument("-l", "--loud", action="store_true", help="shout it")
    parser.add_argument("--status", type=int, default=0, help="exit with this status")
    parser.add_argument("--version", action="version", version="%(prog)s 1.0")
    args = parser.parse_args(argv)
    if args.name == "crash":
        raise RuntimeError("boom")
    greeting = "Hello, %s" % args.name
    for _ in range(args.count):
        print(greeting.upper() + "!" if args.loud else greeting)
    return args.status


if __name__ == "__main__":
    sys.exit(main())
PY
run_gradle "$PYCLI" runBackend "-Pcn1.backend.args=--count 2 --loud Ada" > "$WORKDIR/pycli-run.log" 2>&1 \
  || { cat "$WORKDIR/pycli-run.log"; fail "runBackend for the Python tool"; }
[ "$(grep -c '^HELLO, ADA!$' "$WORKDIR/pycli-run.log")" = "2" ] \
  || { cat "$WORKDIR/pycli-run.log"; fail "the Python tool did not run with its arguments on the JVM"; }
# binary -- the outcomes a caller of a Python tool sees, in CPython's words
check_python_binary() {
  local bin="$1" out code
  out="$("$bin" -c 3 Ada)" || fail "the Python binary failed on valid arguments"
  [ "$(printf '%s\n' "$out" | grep -c '^Hello, Ada$')" = "3" ] || fail "the Python binary printed: $out"
  out="$("$bin" --help)" || fail "--help did not exit 0"
  printf '%s\n' "$out" | grep -q '^usage: launcherprobe \[-h\]' || fail "--help printed: $out"
  printf '%s\n' "$out" | grep -q -- '-c, --count COUNT' || fail "--help did not list --count: $out"
  out="$("$bin" --version)" || fail "--version did not exit 0"
  [ "$out" = "launcherprobe 1.0" ] || fail "--version printed: $out"
  set +e
  "$bin" --status 7 Ada > /dev/null 2>&1; code=$?
  "$bin" --no-such-option Ada > "$WORKDIR/pycli-bad.log" 2>&1; local bad=$?
  "$bin" crash > "$WORKDIR/pycli-crash.log" 2>&1; local crash=$?
  set -e
  [ "$code" = "7" ] || fail "sys.exit(7) exited $code"
  [ "$bad" = "2" ] || { cat "$WORKDIR/pycli-bad.log"; fail "an unknown option exited $bad, not 2"; }
  grep -q "launcherprobe: error: unrecognized arguments: --no-such-option" "$WORKDIR/pycli-bad.log" \
    || { cat "$WORKDIR/pycli-bad.log"; fail "unknown option message"; }
  [ "$crash" = "1" ] || { cat "$WORKDIR/pycli-crash.log"; fail "an uncaught exception exited $crash, not 1"; }
  grep -q "RuntimeError: boom" "$WORKDIR/pycli-crash.log" || { cat "$WORKDIR/pycli-crash.log"; fail "no traceback"; }
}
if command -v clang > /dev/null 2>&1; then
  run_gradle "$PYCLI" backendPackage > "$WORKDIR/pycli-package.log" 2>&1 \
    || { cat "$WORKDIR/pycli-package.log"; fail "backendPackage for the Python tool"; }
  [ -x "$PYCLI/build/launcherprobe" ] || { cat "$WORKDIR/pycli-package.log"; fail "no executable at $PYCLI/build/launcherprobe"; }
  echo "   $(du -h "$PYCLI/build/launcherprobe" | cut -f1) binary"
  check_python_binary "$PYCLI/build/launcherprobe"
elif [ "${CN1_BACKEND_PACKAGE_REQUIRED:-}" = "1" ]; then
  fail "backendPackage needs clang, and CN1_BACKEND_PACKAGE_REQUIRED=1 forbids skipping it"
fi

echo "== migrations"
# The migration tasks launch a class the build generates, and nothing ran them: they
# named the class that holds the scripts, which has no main, and every one of them
# died at start-up. Last in this script, because a server with a migration needs a
# database to start and the steps above start this one without.
if run_gradle "$SVC" backendMigrateInfo > "$WORKDIR/migrate-none.log" 2>&1; then
  cat "$WORKDIR/migrate-none.log"
  fail "backendMigrateInfo succeeded for a backend with no migrations"
fi
grep -q "This module has no migrations to run" "$WORKDIR/migrate-none.log" \
  || { cat "$WORKDIR/migrate-none.log"; fail "backendMigrateInfo did not say the backend has no migrations"; }
mkdir -p "$SVC/src/main/resources/db/migration"
printf 'CREATE TABLE notes (id INTEGER PRIMARY KEY, body VARCHAR(100));\n' \
  > "$SVC/src/main/resources/db/migration/V1__create_notes.sql"
MIGRATE_DB="$WORKDIR/migrate.db"
run_gradle "$SVC" backendMigrate "-Pcn1.datasource.url=$MIGRATE_DB" > "$WORKDIR/migrate.log" 2>&1 \
  || { cat "$WORKDIR/migrate.log"; fail "backendMigrate"; }
grep -q "applied V1__create_notes.sql" "$WORKDIR/migrate.log" \
  || { cat "$WORKDIR/migrate.log"; fail "backendMigrate did not apply the script"; }
run_gradle "$SVC" backendMigrateInfo "-Pcn1.datasource.url=$MIGRATE_DB" > "$WORKDIR/migrate-info.log" 2>&1 \
  || { cat "$WORKDIR/migrate-info.log"; fail "backendMigrateInfo"; }
grep -Eq "^1 .*SQL +SUCCESS" "$WORKDIR/migrate-info.log" \
  || { cat "$WORKDIR/migrate-info.log"; fail "backendMigrateInfo did not list the applied migration"; }
run_gradle "$SVC" backendMigrateValidate "-Pcn1.datasource.url=$MIGRATE_DB" > "$WORKDIR/migrate-validate.log" 2>&1 \
  || { cat "$WORKDIR/migrate-validate.log"; fail "backendMigrateValidate"; }
grep -q "the schema history matches this build's migrations" "$WORKDIR/migrate-validate.log" \
  || { cat "$WORKDIR/migrate-validate.log"; fail "backendMigrateValidate did not confirm the history"; }
echo "   applied, listed and validated"

echo "gradle-initializr-test: OK"
